/**
 * Shader of the nebula.
 *
 * ## The mathematical idea
 *
 * Two layers of fractal noise drifting at different speeds, the second read at
 * a point already displaced by the first: it is that coupling that makes
 * clouds, where two independent layers would only make two superimposed
 * textures. A vignette darkens the edges to give the depth.
 *
 * ## Uniforms
 *
 * - `uTime` — time in seconds, supplied by the engine.
 * - `uResolution` — canvas size in pixels, supplied by the engine.
 * - `uColorA` — the deep background.
 * - `uColorB` — the hue of the clouds.
 * - `uColorC` — the hue of the bright cores.
 * - `uSpeed` — speed at which the two layers drift.
 * - `uScale` — scale of the noise; higher is finer.
 * - `uDepth` — number of octaves of the two layers, and therefore their cost.
 */
export const NEBULA_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uSpeed;
uniform float uScale;
uniform float uDepth;

// Pseudo-random number: projection onto an arbitrary direction, amplified sine,
// fractional part.
float nebulaHash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

// Value noise: smoothed interpolation between the four corners of the cell.
float nebulaNoise(vec2 p) {
  vec2 cell = floor(p);
  vec2 local = fract(p);

  // 3t2 - 2t3: zero derivative at the ends, hence no visible ridge.
  vec2 smoothed = local * local * (3.0 - 2.0 * local);

  float a = nebulaHash(cell);
  float b = nebulaHash(cell + vec2(1.0, 0.0));
  float c = nebulaHash(cell + vec2(0.0, 1.0));
  float d = nebulaHash(cell + vec2(1.0, 1.0));

  return mix(mix(a, b, smoothed.x), mix(c, d, smoothed.x), smoothed.y);
}

// Sum of octaves: each pass twice as fine and twice as weak.
float nebulaFbm(vec2 p, int octaves) {
  float total = 0.0;
  float amplitude = 0.5;
  float normalisation = 0.0;

  for (int i = 0; i < 6; i += 1) {
    if (i >= octaves) break;
    total += nebulaNoise(p) * amplitude;
    normalisation += amplitude;
    p *= 2.0;
    amplitude *= 0.5;
  }

  return total / max(normalisation, 0.0001);
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 p = vUv * vec2(aspect, 1.0) * max(uScale, 0.1);
  float t = uTime * uSpeed;
  int octaves = int(clamp(uDepth, 1.0, 6.0));

  // First layer: the slow masses, the framework of the clouds.
  float mass = nebulaFbm(p + vec2(t * 0.05, t * 0.02), octaves);

  // Second layer: finer, faster, and read at a point displaced by the first.
  // It is that coupling that coils the swirls; two independent layers would
  // only superimpose.
  float swirl = nebulaFbm(p * 1.7 + vec2(-t * 0.11, t * 0.07) + mass * 1.4, octaves);

  vec3 colour = mix(uColorA, uColorB, smoothstep(0.25, 0.85, mass));

  // The bright cores appear only where the two layers reinforce each other: the
  // product stays low almost everywhere, which makes them scarce.
  colour = mix(colour, uColorC, smoothstep(0.45, 0.95, mass * swirl * 2.0));

  // Vignette: darkening the edges gives the depth, without which the sheet
  // stays a wallpaper.
  float fromCentre = length((vUv - 0.5) * vec2(aspect, 1.0));
  colour *= 1.0 - smoothstep(0.35, 0.95, fromCentre) * 0.65;

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Nebula: deep clouds, in two coupled layers of noise.
 *
 * ## The principle
 *
 * Two layers of fractal noise at different speeds, the second read at a point already displaced by the first: the coupling makes the swirls.
 *
 * A vignette darkens the edges — it is what gives the depth, not the noise.
 *
 * ## What this component delegates
 *
 * It carries only what sets it apart: its shader, its settings and its
 * fallback. Reading the tokens, converting them to floats and re-reading them
 * when the theme changes all come from the engine — copying that here would
 * leave as many versions to maintain as there are backgrounds.
 *
 * The fallback is not a precaution: it is shown while the backend loads, when
 * WebGL is missing, when the arbiter refuses the surface — it grants only one
 * per backend — and under reduced motion.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { NEBULA_FRAGMENT } from './nebula.shader.js'

/** What the escape hatch receives. */
export interface NebulaControls {
  /** Colours actually handed to the shader. */
  readonly colours: readonly ShaderColour[]
  /** Reason for the refusal, if there is one. */
  readonly refused: string | undefined
}

/** Props specific to this component. */
export interface NebulaOwnProps {
  /** Speed at which the layers drift. @defaultValue 0.1 */
  speed?: number
  /** Scale of the noise. Higher is finer. @defaultValue 2.2 */
  scale?: number
  /** Number of octaves of the two layers. @defaultValue 4 */
  depth?: number
  /** Tokens whose colours are read. */
  colors?: readonly string[]
  /** Fallback classes. */
  fallback?: string
  /** Escape hatch. */
  onReady?: ReadyCallback<NebulaControls>
}

/** All props. */
export type NebulaProps = Customisable<NebulaOwnProps>

/** Tokens used by default: the background, the clouds, the bright cores. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-violet-500',
  '--o-palette-rose-300',
] as const

/** Default fallback: a frozen gradient, in the same tones. */
const DEFAULT_FALLBACK =
  'o-bg-gradient-to-b o-from-zinc-50 dark:o-from-zinc-950 o-to-violet-950'

/**
 * Nebula.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <Nebula className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function Nebula({
  speed = 0.1,
  scale = 2.2,
  depth = 4,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: NebulaProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: NEBULA_FRAGMENT,
    colors,
    uniforms: { uSpeed: speed, uScale: scale, uDepth: depth },
    name: 'nebula',
    // Every octave is one more noise evaluation per pixel, and there are two
    // layers: it is the setting that weighs, hence the one that is bounded.
    degrade: (quality) => ({
      uDepth: quality === 'low' ? Math.min(depth, 2) : depth,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
